import { useState, KeyboardEvent, ChangeEvent } from 'react';
import { TextField, Tag, Stack } from '@jinx-ui/react';

interface TagInputProps {
  onChange?: (tags: string[]) => void;
}

export default function TagInput({ onChange }: TagInputProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const updateTags = (newTags: string[]) => {
    setTags(newTags);
    onChange?.(newTags);
  };

  const addTag = (rawValue: string) => {
    const value = rawValue.trim();
    if (!value) return;
    if (tags.includes(value)) {
      setInputValue('');
      return;
    }
    updateTags([...tags, value]);
    setInputValue('');
  };

  const removeTag = (tagToRemove: string) => {
    updateTags(tags.filter((tag) => tag !== tagToRemove));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(inputValue);
      return;
    }
    if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  const handleBlur = () => {
    if (inputValue.trim()) {
      addTag(inputValue);
    }
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
  };

  return (
    <Stack className="jx-flex-col" style={{ gap: 'var(--jx-space-2)' }}>
      <TextField
        value={inputValue}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        placeholder="Введите тег и нажмите Enter"
        aria-label="Добавить тег"
      />
      {tags.length > 0 && (
        <Stack
          className="jx-flex-row jx-flex-wrap"
          style={{ gap: 'var(--jx-space-1)' }}
        >
          {tags.map((tag) => (
            <Tag
              key={tag}
              onRemove={() => removeTag(tag)}
              removable
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

